Object.assign(window.TEM8_DICTIONARY, {"blessing":{"media":{"uk":"media/uk/blessing__gb_1.mp3","us":"media/us/blessing__us_1.mp3"},"oxford":{"phon":"ˈblesɪŋ","pos":"noun","senses":[{"en":"God's help and protection, or a prayer asking for this","cn":"上帝的恩宠；祝福；祝颂"},{"en":"approval of or permission for sth","cn":"赞同；许可"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"幸事；福气；好事；福祉；"},{"pos":"[N-COUNT 可数名词]","cn":"支持；赞同；准许；"}]},"examples":[{"en":"Lack of traffic is one of the blessings of country life.","cn":"往来车辆少是乡村生活的一大好处。"},{"en":"He went with his parents' blessing.","cn":"他是得到父母的同意去的。"}]},"blank":{"media":{"uk":"media/uk/blank__gb_1.mp3","us":"media/us/blank__us_1.mp3"},"oxford":{"phon":"blæŋk","pos":"adjective","senses":[{"en":"empty, with nothing written, printed or recorded on it","cn":"空白的"},{"en":"empty; with no pictures, marks or decoration","cn":"空的；无图画（或标记、装饰）的"}]},"collins":{"senses":[{"pos":"[ADJ 形容词]","cn":"空白的；空的；"},{"pos":"[N-COUNT 可数名词]","cn":"空白处；空格；"}]},"examples":[{"en":"I saw her on the bus this morning, but she totally blanked me.","cn":"我今天早晨在公共汽车上见到她，但她连一眼都没瞧我。"},{"en":"Steve looked blank and said he had no idea what I was talking about.","cn":"史蒂夫显得很迷惑，说他不知道我在说什么。"}]},"blackboard":{"oxford":{"phon":"ˈblækbɔːd","pos":"noun","senses":[{"en":"a large board with a smooth black or dark green surface that teachers write on with a piece of chalk","cn":"黑板"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"黑板；"}]},"media":{"uk":"media/uk/blackboard__gb_1.mp3","us":"media/us/blackboard__us_1.mp3","img":["media/ldoce/img/blackboard.jpg"]},"examples":[{"en":"to write on the blackboard","cn":"在黑板上写字"}]},"blankness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"used about something that has nothing inside","cn":""},{"en":"used about a computer screen or a piece of paper that has no writing or pictures on it, or a CD, DVD etc with nothing recorded on it","cn":""}]},"examples":[{"en":"Leave the last page blank .","cn":"","src":"ld"},{"en":"Zoe looked at me with a blank expression.","cn":"","src":"ld"}],"media":{"uk":"media/uk/blankness__gb_1.mp3","us":"media/us/blankness__us_1.mp3"}},"block":{"media":{"img":["media/pic/homes_comp.jpg","media/thumb/flat.jpg","media/ldoce/img/block_ice.jpg"],"uk":"media/uk/block__gb_1.mp3","us":"media/us/block__us_1.mp3"},"oxford":{"phon":"blɒk","pos":"noun","senses":[{"en":"a large piece of a solid material that is square in shape and usually has flat sides （","cn":"方形平面）大块；立方体"},{"en":"( BrE ) a tall building that contains flats or offices; buildings that form part of a school, hospital, etc. which are used for a particular purpose （","cn":"公寓、办公、教学、医院等）大楼；（成组建筑中的）一栋楼房"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"大楼；大厦；"},{"pos":"[N-COUNT 可数名词]","cn":"街区；"}]},"examples":[{"en":"Over the years she had tried to block out that part of her life.","cn":"多年来她努力想把她生命中的那一段经历从记忆中抹去。"},{"en":"The three-hour class is divided into four blocks of 45 minutes each.","cn":"三小时的课分成四节，每节 45 分钟。"}]},"blunt":{"media":{"uk":"media/uk/blunt__gb_1.mp3","us":"media/us/blunt__us_1.mp3"},"oxford":{"phon":"blʌnt","pos":"adjective","senses":[{"en":"without a sharp edge or point","cn":"不锋利的；钝的"},{"en":"very direct; saying exactly what you think without trying to be polite","cn":"嘴直的；直言的"}]},"collins":{"senses":[{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"直率的；不客气的；直言不讳的；"},{"pos":"[ADJ 形容词]","cn":"物体钝的，不锋利的，不尖的；"}]},"examples":[{"en":"To be blunt, your work is appalling.","cn":"坦率地说，你的活干得糟透了。"},{"en":"Age hadn't blunted his passion for adventure.","cn":"岁月没有冲淡他的冒险激情。"}]},"blanks":{"oxford":{"phon":"blæŋk","pos":"adjective","senses":[{"en":"empty, with nothing written, printed or recorded on it","cn":"空白的"},{"en":"empty; with no pictures, marks or decoration","cn":"空的；无图画（或标记、装饰）的"}]},"collins":{"senses":[{"pos":"[ADJ 形容词]","cn":"空白的；空的；"},{"pos":"[N-COUNT 可数名词]","cn":"空白处；空格；"}]},"media":{"uk":"media/uk/blank__gb_1.mp3","us":"media/us/blank__us_1.mp3"}},"blurred":{"media":{"uk":"media/uk/blurred__gb_1.mp3","us":"media/us/blurred__us_1.mp3"},"oxford":{"phon":"blɜːd","pos":"adj.","senses":[{"en":"not clear; without a clear outline or shape","cn":"模糊不清的"},{"en":"difficult to remember clearly","cn":"记不清的"}]},"examples":[{"en":"She suffered from dizziness and blurred vision.","cn":"她饱受头晕目眩之苦。"},{"en":"blurred distinctions/boundaries","cn":"含混不清的区别/界线"}]},"blockbuster":{"media":{"uk":"media/uk/blockbuster__gb_1.mp3","us":"media/us/blockbuster__us_1.mp3"},"oxford":{"phon":"ˈblɒkbʌstə(r)","pos":"noun","senses":[{"en":"something very successful, especially a very successful book or film/movie","cn":"一鸣惊人的事物；（尤指）非常成功的书（或电影）"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"轰动一时的电影；一度热卖的畅销书；"}]},"examples":[{"en":"a Hollywood blockbuster","cn":"一部好莱坞大片"},{"en":"a blockbusting performance","cn":"引起轰动的演出"}]},"bloated":{"media":{"uk":"media/uk/bloated__gb_1.mp3","us":"media/us/bloated__us_1.mp3"},"oxford":{"phon":"ˈbləʊtɪd","pos":"adj.","senses":[{"en":"full of liquid or gas and therefore bigger than normal, in a way that is unpleasant","cn":"膨胀的；肿胀的；臃肿的"},{"en":"full of food and feeling uncomfortable","cn":"饮食过度的；胃胀的"}]},"collins":{"senses":[{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"身体或身体某部位肿胀的，膨胀的，发胀的；"},{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"吃撑了的；肚子胀的；"}]},"examples":[{"en":"I felt bloated after the huge meal they'd served.","cn":"吃过他们提供的大餐后，我觉得肚子胀得很。"},{"en":"a bloated body floating in the canal","cn":"运河里一具发胀的浮尸"}]},"blink":{"oxford":{"phon":"blɪŋk","pos":"verb","senses":[{"en":"when you blink or blink your eyes or your eyes blink , you shut and open your eyes quickly","cn":"眨眼睛"},{"en":"to shine with an unsteady light; to flash on and off","cn":"闪烁"}]},"collins":{"senses":[{"pos":"[VERB 动词]","cn":"眨眼；"},{"pos":"[VERB 动词]","cn":"灯光闪烁，闪动，忽明忽灭；"}]},"media":{"uk":"media/uk/blink__gb_1.mp3","us":"media/us/blink__us_1.mp3"},"examples":[{"en":"When I told him the news he didn't even blink (= showed no surprise at all).","cn":"我把那个消息告诉他时，他眼都没眨一下。"},{"en":"He blinked in the bright sunlight.","cn":"他在强烈的阳光下直眨眼睛。"}]},"blend":{"media":{"uk":"media/uk/blend__gb_1.mp3","us":"media/us/blend__us_1.mp3"},"oxford":{"phon":"blend","pos":"verb","senses":[{"en":"to mix two or more substances together","cn":"使混合；掺和"},{"en":"to form a mixture with sth （","cn":"和某物）混合；融合"}]},"collins":{"senses":[{"pos":"[V-RECIP-ERG ]","cn":"使混合；调和；掺和；"},{"pos":"[N-COUNT 可数名词]","cn":"有用或令人愉快的事物的融合，混合，组合；"}]},"examples":[{"en":"Their music blends traditional and modern styles.","cn":"他们的音乐融合了传统和现代风格。"},{"en":"Beat the butter and sugar; then blend in the egg.","cn":"把黄油和糖打好，然后调入鸡蛋。"}]},"blowing":{"oxford":{"phon":"bləʊ","pos":"verb","senses":[{"en":"to send out air from the mouth","cn":"吹"},{"en":"when the wind or a current of air blows , it is moving; when it blows , the wind is blowing","cn":"刮；吹"}]}},"blockage":{"oxford":{"phon":"ˈblɒkɪdʒ","pos":"noun","senses":[{"en":"a thing that blocks flow or movement, for example of a liquid in a narrow place","cn":"造成阻塞的东西；阻塞物"},{"en":"the state of being blocked","cn":"堵塞；阻塞"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"堵塞物；障碍物；堵塞；"}]},"media":{"uk":"media/uk/blockage__gb_1.mp3","us":"media/us/blockage__us_1.mp3"},"examples":[{"en":"a blockage in an artery/a pipe/a drain","cn":"动脉/管道/排水沟堵塞物"},{"en":"to cause/clear the blockage","cn":"引起/排除阻塞"}]},"blind":{"media":{"uk":"media/uk/blind__gb_1.mp3","us":"media/us/blind__us_1.mp3","img":["media/ldoce/img/ldoce_028.png"]},"oxford":{"phon":"blaɪnd","pos":"adjective","senses":[{"en":"not able to see","cn":"瞎的；失明的"},{"en":"people who are blind","cn":"盲人"}]},"collins":{"senses":[{"pos":"[ADJ 形容词]","cn":"盲的；瞎的；失明的；"},{"pos":"[VERB 动词]","cn":"使…看不见；使…失明；"}]},"examples":[{"en":"I must have been blind not to realize the danger we were in.","cn":"当时我一定是眼瞎了，竟然没有意识到我们所处的危险。"},{"en":"When she went outside she was temporarily blinded by the sun.","cn":"走出户外时，她一时被阳光照得眼睛昏花。"}]},"blood":{"media":{"uk":"media/uk/blood__gb_1.mp3","us":"media/us/blood__us_1.mp3"},"oxford":{"phon":"blʌd","pos":"noun","senses":[{"en":"the red liquid that flows through the bodies of humans and animals","cn":"血"},{"en":"( in adjectives","cn":"构成形容词 ) having the type of blood mentioned 有 … 类型的血的"}]},"collins":{"senses":[{"pos":"[N-UNCOUNT 不可数名词]","cn":"血；血液；"},{"pos":"[N-UNCOUNT 不可数名词]","cn":"血统；出身；门第；家世；"}]},"examples":[{"en":"Blood was pouring out of a cut on her head.","cn":"血不断地从她头上的伤口中涌出。"},{"en":"He lost a lot of blood in the accident.","cn":"他在那场事故中流了很多血。"}]},"blob":{"oxford":{"phon":"blɒb","pos":"noun","senses":[{"en":"a small amount or drop of sth, especially a liquid; a small area of colour （","cn":"尤指液体的）一点，一滴；（颜色的）一小片，斑点"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"黏稠液体的一滴，一团；"},{"pos":"[N-COUNT 可数名词]","cn":"模糊不清的一团，一点；"}]},"media":{"uk":"media/uk/blob__gb_1.mp3","us":"media/us/blob__us_1.mp3"},"examples":[{"en":"a pink blob","cn":"粉红色斑点"},{"en":"a blob of ink","cn":"一滴墨水"}]},"blue-collar":{"oxford":{"phon":"","pos":"adj.","senses":[{"en":"connected with people who do physical work in industry","cn":"从事体力劳动的；蓝领的"}]},"collins":{"senses":[{"pos":"[ADJ 形容词]","cn":"蓝领的；从事体力劳动的；"}]},"media":{"uk":"media/uk/blue_collar_1_gb_1.mp3","us":"media/us/blue_collar_1_us_1.mp3"},"examples":[{"en":"blue-collar workers/voters/votes","cn":"蓝领工人/选民/选票"}]},"blossom":{"media":{"img":["media/pic/tree_bark_comp.jpg","media/thumb/twig.jpg"],"uk":"media/uk/blossom__gb_1.mp3","us":"media/us/blossom__us_1.mp3"},"oxford":{"phon":"ˈblɒsəm","pos":"noun","senses":[{"en":"a flower or a mass of flowers, especially on a fruit tree or bush （","cn":"尤指果树或灌木的）花朵，花簇"},{"en":"to produce blossom","cn":"开花"}]},"collins":{"senses":[{"pos":"[N-VAR 可变名词]","cn":"树木的花， 花簇；"},{"pos":"[VERB 动词]","cn":"兴盛；变得有魅力；变得成功；"}]},"examples":[{"en":"She has visibly blossomed over the last few months.","cn":"她近几个月以来身体明显好多了。"},{"en":"Their friendship blossomed into love.","cn":"他们的友谊发展成了爱情。"}]},"bloodshot":{"oxford":{"phon":"ˈblʌdʃɒt","pos":"adj.","senses":[{"en":"with the part that is usually white full of red lines because of lack of sleep, etc.","cn":"布满血丝的"}]},"collins":{"senses":[{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"眼睛充血的，布满血丝的；"}]},"media":{"uk":"media/uk/bloodshot__gb_1.mp3","us":"media/us/bloodshot__us_1.mp3"}},"bluff":{"media":{"uk":"media/uk/bluff__gb_1.mp3","us":"media/us/bluff__us_1.mp3"},"oxford":{"phon":"blʌf","pos":"verb","senses":[{"en":"to try to make sb believe that you will do sth that you do not really intend to do, or that you know sth that you do not really know","cn":"虚张声势；唬人；吹牛"},{"en":"to make sb do sth by tricking them, especially by pretending you have more experience, knowledge, etc. than you really have","cn":"靠吹牛哄人 …"}]},"collins":{"senses":[{"pos":"[N-VAR 可变名词]","cn":"double bluff"},{"pos":"[PHRASE 短语]","cn":"因料到对方不敢行动而要求…摊牌，接受…的挑战；"}]},"examples":[{"en":"He said he would resign if he didn't get more money, but it was only a bluff.","cn":"他说如果不给他加薪他就辞职，但那不过是虚张声势而已。"},{"en":"I don't think he'll shoot — I think he's just bluffing.","cn":"我认为他不会开枪，我想他不过是在吓唬人。"}]},"blamed":{"oxford":{"phon":"bleɪm","pos":"verb","senses":[{"en":"to think or say that sb/sth is responsible for sth bad","cn":"把 … 归咎于；责怪；指责"},{"en":"to be responsible for sth bad","cn":"对（坏事）负有责任"}]}},"blur":{"media":{"uk":"media/uk/blur__gb_1.mp3","us":"media/us/blur__us_1.mp3"},"oxford":{"phon":"blɜː(r)","pos":"noun","senses":[{"en":"a shape that you cannot see clearly, often because it is moving too fast （","cn":"移动的）模糊形状"},{"en":"something that you cannot remember clearly","cn":"模糊的记忆"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"模糊形状；模糊的区域；"},{"pos":"[V-ERG 及物/不及物动词]","cn":"使变得模糊不清；"}]},"examples":[{"en":"The differences between art and life seem to have blurred.","cn":"艺术和生活之间的差别似乎已变得模糊不清。"},{"en":"His arm was a rapid blur of movement as he struck.","cn":"他出击时胳膊快速一晃，令人眼花缭乱。"}]},"bleak":{"media":{"uk":"media/uk/bleak__gb_1.mp3","us":"media/us/bleak__us_1.mp3"},"oxford":{"phon":"bliːk","pos":"adj.","senses":[{"en":"not encouraging or giving any reason to have hope","cn":"不乐观的；无望的；暗淡的"},{"en":"cold and unpleasant","cn":"阴冷的"}]},"collins":{"senses":[{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"情形没有希望的，前景暗淡的；"},{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"地方凄清的，荒凉的，萧瑟的；"}]},"examples":[{"en":"‘There seems no hope,’ she said bleakly. “","cn":"好像没希望了。”她黯然地说。"},{"en":"The future looks bleak for the fishing industry.","cn":"渔业前景暗淡。"}]},"blindly":{"media":{"uk":"media/uk/blindly__gb_1.mp3","us":"media/us/blindly__us_1.mp3"},"oxford":{"phon":"ˈblaɪndli","pos":"adv.","senses":[{"en":"without being able to see what you are doing","cn":"摸黑地；在黑暗中"},{"en":"without thinking about what you are doing","cn":"不加思考地；盲目地"}]},"collins":{"senses":[{"pos":"[ADV-GRADED 副词]","cn":"blind"}]},"examples":[{"en":"He wanted to decide for himself instead of blindly following his parents' advice.","cn":"他想自己拿主意，而不是盲目听从他父母的意见。"},{"en":"She groped blindly for the light switch in the dark room.","cn":"她在黑暗的房间里摸索电灯开关。"}]},"black":{"media":{"uk":"media/uk/black__gb_1.mp3","us":"media/us/black__us_1.mp3"},"oxford":{"phon":"blæk","pos":"adjective","senses":[{"en":"having the very darkest colour, like night or coal","cn":"黑的；黑色的"},{"en":"without light; completely dark","cn":"黑暗的；漆黑的"}]},"collins":{"senses":[{"pos":"[COLOUR 颜色词]","cn":"黑色；"},{"pos":"[ADJ 形容词]","cn":"人黑色人种的；尤指非洲黑人的；"}]},"examples":[{"en":"It's been another black day for the north-east with the announcement of further job losses.","cn":"东北部又经历了一个黑色的日子，当地公布的失业人数再度上升。"},{"en":"‘Good place to bury the bodies,’ she joked with black humour. “","cn":"真是个掩埋尸体的风水宝地。”她以黑色幽默打趣道。"}]},"blade":{"media":{"img":["media/pic/blade_comp.jpg","media/thumb/blade.jpg"],"uk":"media/uk/blade__gb_1.mp3","us":"media/us/blade__us_1.mp3"},"oxford":{"phon":"bleɪd","pos":"noun","senses":[{"en":"the flat part of a knife, tool or machine, which has a sharp edge or edges for cutting","cn":"刀身；刀片；刀刃"},{"en":"one of the flat parts that turn around in an engine or on a helicopter （","cn":"机器上旋转的）叶片；桨叶"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"刃；锋；"},{"pos":"[N-COUNT 可数名词]","cn":"螺旋桨的叶片；"}]},"examples":[{"en":"rotor blades on a helicopter","cn":"直升机的旋翼"},{"en":"the blades of a propeller","cn":"螺旋桨叶"}]},"blame":{"oxford":{"phon":"bleɪm","pos":"verb","senses":[{"en":"to think or say that sb/sth is responsible for sth bad","cn":"把 … 归咎于；责怪；指责"},{"en":"to be responsible for sth bad","cn":"对（坏事）负有责任"}]},"collins":{"senses":[{"pos":"[VERB 动词]","cn":"责怪；怪罪；归咎于；"},{"pos":"[N-UNCOUNT 不可数名词]","cn":"对坏事应负的责任；"}]},"media":{"uk":"media/uk/blame__gb_1.mp3","us":"media/us/blame__us_1.mp3"},"examples":[{"en":"‘I just slammed the phone down when he said that.’ ‘I don't blame you!’ “","cn":"他一说那话我就啪地一下挂了电话。” “你做得对！”"},{"en":"Call her if you like, but don't blame me if she's angry.","cn":"你想给她打电话就打吧，不过要是她生气就别怪我。"}]},"blessed":{"media":{"uk":"media/uk/blessed__gb_2.mp3","us":"media/us/blessed__us_2.mp3"},"oxford":{"phon":"ˈblesɪd","pos":"adj.","senses":[{"en":"holy","cn":"神圣的"},{"en":"(in religious language) lucky （","cn":"宗教用语）有福的"}]},"collins":{"senses":[{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"拥有…的；享有…的；"},{"pos":"[ADJ 形容词]","cn":"令人快乐的；可喜的；美好的；"}]},"examples":[{"en":"I can't see a blessed thing without my glasses.","cn":"我不戴眼镜根本看不清什么东西。"},{"en":"The kitchen was warm and blessedly familiar.","cn":"厨房又温暖又亲切温馨。"}]},"blue":{"media":{"uk":"media/uk/blue__gb_1.mp3","us":"media/us/blue__us_1.mp3"},"oxford":{"phon":"bluː","pos":"adjective","senses":[{"en":"having the colour of a clear sky or the sea/ocean on a clear day","cn":"蓝色的；天蓝色的；蔚蓝色的"},{"en":"looking slightly blue in colour because the person is cold or cannot breathe easily （","cn":"由于冷或呼吸困难）发青的，青紫的"}]},"collins":{"senses":[{"pos":"[COLOUR 颜色词]","cn":"蓝色；天蓝色；"},{"pos":"[N-PLURAL 复数名词]","cn":"蓝调音乐，布鲁斯音乐源于美国南部黑人音乐家，节奏缓慢，旋律感强；"}]},"examples":[{"en":"You can argue till you're blue in the face, but you won't change my mind.","cn":"你可以费尽口舌，但改变不了我的主意。"},{"en":"The room was decorated in vibrant blues and yellows.","cn":"房间内部以鲜明的蓝色和黄色作为装饰。"}]},"blows":{"oxford":{"phon":"bləʊ","pos":"verb","senses":[{"en":"to send out air from the mouth","cn":"吹"},{"en":"when the wind or a current of air blows , it is moving; when it blows , the wind is blowing","cn":"刮；吹"}]}},"blow":{"oxford":{"phon":"bləʊ","pos":"verb","senses":[{"en":"to send out air from the mouth","cn":"吹"},{"en":"when the wind or a current of air blows , it is moving; when it blows , the wind is blowing","cn":"刮；吹"}]},"collins":{"senses":[{"pos":"[VERB 动词]","cn":"风吹，刮；"},{"pos":"[V-ERG 及物/不及物动词]","cn":"风把…吹到；吹到，吹向；"}]},"media":{"uk":"media/uk/blow__gb_1.mp3","us":"media/us/blow__us_1.mp3"},"examples":[{"en":"A DVD music system plays discs that look like CDs, but blows them out of the water. * DVD","cn":"音乐播放机里放的碟片看似 CD，却要比 CD 强多了。"},{"en":"What we discovered blew apart all our preconceptions about this fascinating species.","cn":"我们的发现将我们对这一奇妙物种的先入之见全盘推翻了。"}]},"blonde":{"media":{"uk":"media/uk/blonde__gb_1.mp3","us":"media/us/blonde__us_1.mp3"},"oxford":{"phon":"blɒnd","pos":"adjective","senses":[{"en":"pale gold in colour","cn":"金黄色的"},{"en":"having blonde hair","cn":"头发金黄的"}]},"collins":{"senses":[{"pos":"[COLOUR 颜色词]","cn":"头发金色，浅棕色，浅黄色；"},{"pos":"[ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词]","cn":"金发的；浅色头发的；"}]},"examples":[{"en":"Is she a natural blonde (= Is her hair naturally blonde)?","cn":"她的头发原本就是金黄色吗？"},{"en":"a small, blond boy","cn":"一个金发小男孩"}]},"blues":{"oxford":{"phon":"bluːz","pos":"noun","senses":[{"en":"a type of slow sad music with strong rhythms, developed by African American musicians in the southern US","cn":"布鲁斯音乐， （台）蓝调 （源于美国南部黑人，节奏感强、缓慢忧郁）"},{"en":"a blues song","cn":"布鲁斯歌曲； （台）蓝调歌曲"}]},"media":{"uk":"media/uk/blues__gb_1.mp3","us":"media/us/blues__us_1.mp3"},"examples":[{"en":"the Monday morning blues","cn":"星期一早晨的郁闷情绪"},{"en":"a blues band/singer","cn":"布鲁斯乐队/歌手"}]},"blackness":{"media":{"uk":"media/uk/blackness__gb_1.mp3","us":"media/us/blackness__us_1.mp3"},"collins":{"senses":[{"pos":"[N-UNCOUNT 不可数名词]","cn":"漆黑；黑暗；"}]},"examples":[{"en":"She peered out into the blackness of the night.","cn":"她凝视着外面黑沉沉的夜色。"},{"en":"It was still pitch black (= very dark ) out.","cn":""}]},"blocked":{"oxford":{"phon":"blɒk","pos":"noun","senses":[{"en":"a large piece of a solid material that is square in shape and usually has flat sides （","cn":"方形平面）大块；立方体"},{"en":"( BrE ) a tall building that contains flats or offices; buildings that form part of a school, hospital, etc. which are used for a particular purpose （","cn":"公寓、办公、教学、医院等）大楼；（成组建筑中的）一栋楼房"}]},"collins":{"senses":[{"pos":"[N-COUNT 可数名词]","cn":"大楼；大厦；"},{"pos":"[N-COUNT 可数名词]","cn":"街区；"}]},"media":{"img":["media/pic/homes_comp.jpg","media/thumb/flat.jpg"],"uk":"media/uk/block__gb_1.mp3","us":"media/us/block__us_1.mp3"}},"blunders":{"oxford":{"phon":"ˈblʌndə(r)","pos":"noun","senses":[{"en":"a stupid or careless mistake","cn":"愚蠢（或粗心）的错误"},{"en":"to make a stupid or careless mistake","cn":"犯愚蠢的（或粗心的）错误"}]}},"blunter":{"oxford":{"phon":"blʌnt","pos":"adjective","senses":[{"en":"without a sharp edge or point","cn":"不锋利的；钝的"},{"en":"very direct; saying exactly what you think without trying to be polite","cn":"嘴直的；直言的"}]}},"blushing":{"oxford":{"phon":"blʌʃ","pos":"verb","senses":[{"en":"to become red in the face because you are embarrassed or ashamed （","cn":"因尴尬或害羞）脸红，涨红了脸"},{"en":"to be ashamed or embarrassed about sth （","cn":"因某事）羞愧，尴尬"}]}},"blankets":{"oxford":{"phon":"ˈblæŋkɪt","pos":"noun","senses":[{"en":"a large cover, often made of wool, used especially on beds to keep people warm","cn":"毯子；毛毯"},{"en":"a thick layer or covering of sth","cn":"厚层；厚的覆盖层"}]}},"blond":{"oxford":{"phon":"blɒnd","pos":"adjective","senses":[{"en":"pale gold in colour","cn":"金黄色的"},{"en":"having blonde hair","cn":"头发金黄的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/blond0205.mp3","us":"media/ldoce/hwd/ame/e/blond1.mp3"}},"blocks":{"oxford":{"phon":"blɒk","pos":"noun","senses":[{"en":"a large piece of a solid material that is square in shape and usually has flat sides （","cn":"方形平面）大块；立方体"},{"en":"( BrE ) a tall building that contains flats or offices; buildings that form part of a school, hospital, etc. which are used for a particular purpose （","cn":"公寓、办公、教学、医院等）大楼；（成组建筑中的）一栋楼房"}]}},"blushes":{"oxford":{"phon":"blʌʃ","pos":"verb","senses":[{"en":"to become red in the face because you are embarrassed or ashamed （","cn":"因尴尬或害羞）脸红，涨红了脸"},{"en":"to be ashamed or embarrassed about sth （","cn":"因某事）羞愧，尴尬"}]}},"blocking":{"oxford":{"phon":"blɒk","pos":"noun","senses":[{"en":"a large piece of a solid material that is square in shape and usually has flat sides （","cn":"方形平面）大块；立方体"},{"en":"( BrE ) a tall building that contains flats or offices; buildings that form part of a school, hospital, etc. which are used for a particular purpose （","cn":"公寓、办公、教学、医院等）大楼；（成组建筑中的）一栋楼房"}]}},"blades":{"oxford":{"phon":"bleɪd","pos":"noun","senses":[{"en":"the flat part of a knife, tool or machine, which has a sharp edge or edges for cutting","cn":"刀身；刀片；刀刃"},{"en":"one of the flat parts that turn around in an engine or on a helicopter （","cn":"机器上旋转的）叶片；桨叶"}]}},"blister":{"collins":{"senses":[{"pos":"N-COUNT","cn":"（皮肤上因烫伤或反复摩擦而起的）水疱","en":"A blister is a painful swelling on the surface of your skin. Blisters contain a clear liquid and are usually caused by heat or by something repeatedly rubbing your skin."},{"pos":"V-ERG","cn":"（使）（皮肤）长水疱","en":"When your skin blisters or when something blisters it, blisters appear on it. 【语法信息】：V 【语法信息】：V n 【语法信息】：V-ed The affected skin turns red and may ... 受感染的皮肤会变红，还有可能起水疱。 The sap of this plant s the skin. 这种植物的汁液会使皮肤起水疱。 ...pausing to bathe t"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a mark on your skin that spoils its appearance","cn":""},{"en":"a small dark, sometimes raised, mark on your skin","cn":""},{"en":"small light brown marks on your skin, especially on your face but also on your arms, shoulders etc","cn":""}]},"collocations":{"phrases":["ADV. badly Her feet were badly blistered."]},"media":{"uk":"media/ldoce/hwd/bre/0/blister_v0205.mp3","us":"media/ldoce/hwd/ame/b/blister1.mp3"},"examples":[{"en":"Her face had been blistered by the sun.","cn":"她的脸让太阳晒起水疱了。"},{"en":"His skin was beginning to blister.","cn":"他的皮肤开始起疱。"}]},"blasphemous":{"collins":{"senses":[{"pos":"ADJ","cn":"亵渎神明（或宗教）的","en":"You can describe someone who shows disrespect for God or a religion as blasphemous . You can also describe what they are saying or doing as blasphemous . She was accused of being ... 她被控亵渎神明。 Critics attacked the film as . 评论家抨击这部电影亵渎神明。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something you say or do that is insulting to God or people’s religious beliefs","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Blasphemous is an adjective that describes profane words and actions, especially when they are connected to something religious. If you draw Jesus Christ wearing lipstick or call Buddha a fat slob, you're displaying blasphemous behavior."}]},"collocations":{"phrases":["VERBS be, seem | consider sth | declare sth, deem sth The book was declared blasphemous and all copies ordered to be burnt.","ADV. almost"]},"media":{"uk":"media/ldoce/hwd/bre/e/blasphemy0205.mp3","us":"media/ldoce/hwd/ame/2/blasphemy.mp3"},"examples":[{"en":"Many people found the film blasphemous.","cn":"很多人觉得那部电影亵渎了神灵。"}]},"blizzard":{"collins":{"senses":[{"pos":"N-COUNT","cn":"大风雪；暴风雪","en":"A blizzard is a very bad snowstorm with strong winds."},{"pos":"N-COUNT","cn":"（指令人反感或恼火的事情）大量，铺天盖地","en":"You can refer to a large number of things that you do not like or which annoy you as a blizzard of those things. 【搭配模式】：usu sing 【语用信息】：disapproval 【FIELD标签】：WRITTEN 笔语 Retailers were hit with a of new products and brands in all shapes, siz"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a period of very bad weather when there is a lot of rain or snow, strong winds, and often lightning","cn":""},{"en":"a storm in which there is a lot of thunder (= loud noise in the sky ) and lightning (= flashes of light in the sky )","cn":""},{"en":"a storm that has very strong fast winds and that moves over water – used about storms in the North Atlantic Ocean","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A blizzard is a large winter storm, characterized by heavy snowfall and accompanied by high winds. We're not talking flurry or a snowsquall . It's the kind of snow storm you read about."}]},"collocations":{"phrases":["ADJ. fierce, howling","VERB + BLIZZARD blow After a short while it began to blow a blizzard.","BLIZZARD + VERB hit (sth), strike (sth) The blizzard struck while we were still on the mountain. | blow, rage","BLIZZARD + NOUN conditions","PREP. in/into ~ We got stuck in a howling blizzard. | through ~ He fought his way through the blizzard."]},"media":{"uk":"media/ldoce/hwd/bre/d/blizzard0205.mp3","us":"media/ldoce/hwd/ame/7/blizzard.mp3"},"examples":[{"en":"a raging/howling blizzard","cn":"猛烈的/怒吼着的暴风雪"},{"en":"a blizzard of documents","cn":"一大堆棘手的文件"}]},"blacklist":{"collins":{"senses":[{"pos":"N-COUNT","cn":"黑名单","en":"If someone is on a blacklist , they are seen by a government or other organization as being one of a number of people who cannot be trusted or who have done something wrong. A government official disclosed that they were on a secret ... 一名政"},{"pos":"VERB","cn":"把…列入黑名单","en":"If someone is blacklisted by a government or organization, they are put on a blacklist. 【语法信息】： be V-ed 【语法信息】：V-ed 【搭配模式】：usu passive He has been ed since being convicted of possessing marijuana in 1969. 他自从1969年因持有大麻而被定罪后就被列入了黑名单。 ...the "}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say that someone must not do something, and stop them doing it. Not allow is more formal than not let","cn":""},{"en":"to tell someone that they should not do something, especially because it is dangerous or harmful","cn":""},{"en":"to say clearly and strongly that someone should not do something","cn":""}]},"collocations":{"phrases":["VERB + BLACKLIST place sb on, put sb on | draw up","PREP. on a/the ~ She was on the company's blacklist."]},"media":{"uk":"media/ldoce/hwd/bre/3/blacklist_v0205.mp3","us":"media/ldoce/hwd/ame/6/blacklist.mp3"},"examples":[{"en":"She was blacklisted by all the major Hollywood studios because of her political views.","cn":"由于她的政见，所有好莱坞大制片公司都拒绝用她。"},{"en":"Many people in the industry were blacklisted for their communist sympathies.","cn":"行业里有许多人因为同情共产党而被列入了黑名单。"}]},"bloom":{"collins":{"senses":[{"pos":"N-COUNT","cn":"花；花朵","en":"A bloom is the flower on a plant. 【FIELD标签】：LITERARY or TECHNICAL 文或术语 ...the sweet fragrance of the white s... 白色花朵的芳香 Harry carefully picked the . 哈里小心翼翼地摘下那朵花。"},{"pos":"PHRASE","cn":"正开花的；花朵绽放的","en":"A plant or tree that is in bloom has flowers on it. ...a pink climbing rose in full . 盛开的粉色藤蔓玫瑰 ...the sweet smell of the blackberry in . 绽放的黑莓花的芬芳"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a flower or flowers","cn":"花"},{"en":"with the flowers fully open 〔","cn":"鲜花〕盛开﹐怒放"},{"en":"the healthy happy appearance that someone has, especially when they are young","cn":"健康的气色〔尤指人年轻时〕"}]},"vocab":{"pos":"1 v n 2 n 3 n","senses":[{"en":"A bloom is a flower. You might mark the beginning of spring by the very first bloom you see in your garden."}]},"collocations":{"phrases":["ADJ. beautiful, exquisite, perfect a tree with exquisite blooms | fragrant | exotic","VERB + BLOOM bear, have, produce | burst into, come into The spring flowers have come into bloom.","BLOOM + VERB appear The small white blooms appear in May. | fade The blooms have started to fade now.","PREP. in ~ banks of rhododendrons in bloom","PHRASES in full bloom The roses are now in full bloom."]},"media":{"uk":"media/ldoce/hwd/bre/8/bloom_n0205.mp3","us":"media/ldoce/hwd/ame/1/bloom1.mp3"},"examples":[{"en":"The children had bloomed during their stay on the farm.","cn":"孩子们在农场期间健康活泼有生气。"},{"en":"Most roses will begin to bloom from late May.","cn":"大多数玫瑰从五月末开始开花。"}]},"blackmail":{"collins":{"senses":[{"pos":"N-UNCOUNT","cn":"勒索；敲诈；讹诈","en":"Blackmail is the action of threatening to reveal a secret about someone, unless they do something you tell them to do, such as giving you money. It looks like the pictures were being used for ... 这些照片好像被用于敲诈勒索。 Opponents accused him of and "},{"pos":"N-UNCOUNT","cn":"（情感或道德上的）迫使，胁迫","en":"If you describe an action as emotional or moral blackmail , you disapprove of it because someone is using a person's emotions or moral values to persuade them to do something against their will. 【语用信息】：disapproval The tactics employed can r"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to force someone to do something that they do not want to do. Make is less formal than force","cn":""},{"en":"to keep trying to persuade someone to do something, for example by saying that it is their duty or that it will help other people","cn":""},{"en":"to try to make someone do something by persuading them very strongly and making them feel that they should do it","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"To blackmail someone is to use secret information to get something from them, usually money. Blackmailing is a crime."}]},"collocations":{"phrases":["ADV. virtually","VERB + BLACKMAIL attempt to, try to","PREP. into She says she was virtually blackmailed into giving up her claim to the property."]},"media":{"uk":"media/ldoce/hwd/bre/d/blackmail_n0205.mp3","us":"media/ldoce/hwd/ame/4/blackmail.mp3"},"examples":[{"en":"The President said he wouldn't be blackmailed into agreeing to the terrorists' demands.","cn":"总统说他不会因受恐怖分子的威胁而答应他们的要求。"},{"en":"She blackmailed him for years by threatening to tell the newspapers about their affair.","cn":"她以向报界公开他们的恋情要挟了他很多年。"}]},"blemish":{"collins":{"senses":[{"pos":"N-COUNT","cn":"污点；瑕疵；疤痕","en":"A blemish is a small mark on something that spoils its appearance. Every piece is closely scrutinised, and if there is the slightest on it, it is rejected. 每一件物品都经过严格检查，稍有瑕疵就会被退回。"},{"pos":"N-COUNT","cn":"缺点；缺陷；不足","en":"A blemish on something is a small fault in it. 【搭配模式】：oft N on n This is the one on an otherwise resounding success. 如果没有这个小小的失误，这就是一次彻底的胜利。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a mark on your skin that spoils its appearance","cn":""},{"en":"a small dark, sometimes raised, mark on your skin","cn":""},{"en":"small light brown marks on your skin, especially on your face but also on your arms, shoulders etc","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A blemish is a small flaw. If you borrow your brother's brand new bicycle, you'd better be careful — what might seem like the tiniest blemish to you might be a horribly ruined paint job to him."}]},"collocations":{"phrases":["ADJ. minor, slight","VERB + BLEMISH have The police say the suspect has a slight blemish on his left cheek.","PREP. without (a) ~ (figurative) He was pilloried, but she escaped without blemish."]},"media":{"uk":"media/ldoce/hwd/bre/0/blemish_n0205.mp3","us":"media/ldoce/hwd/ame/a/blemish1.mp3"},"examples":[{"en":"( figurative ) His reputation is without a blemish.","cn":"他的名誉可说是白璧无瑕。"},{"en":"His reputation is without a blemish.","cn":""}]},"bloodstream":{"collins":{"senses":[{"pos":"N-COUNT","cn":"血流；血液","en":"Your bloodstream is the blood that flows around your body. 【搭配模式】：usu sing The disease releases toxins into the . 这种病会释放毒素到血液中。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the blood flowing in your body","cn":"体内循环的血液﹐血流"}]},"collocations":{"phrases":["VERB + BLOODSTREAM enter | absorb sth into The drug is quickly absorbed into the bloodstream.","PREP. in sb's/the ~ Traces of banned substances were detected in his bloodstream. | into sb's/the ~ Bacteria was introduced into his bloodst"]},"media":{"uk":"media/ldoce/hwd/bre/3/bloodstream0205.mp3","us":"media/ldoce/hwd/ame/b/bloodstream.mp3"},"examples":[{"en":"They injected the drug directly into her bloodstream.","cn":"他们把麻醉剂直接注射到她的血液里。"},{"en":"The drug is injected directly into the bloodstream.","cn":"这种药物直接注射到血液中。"}]},"bliss":{"collins":{"senses":[{"pos":"N-UNCOUNT","cn":"巨大的幸福；极乐","en":"Bliss is a state of complete happiness. It was a scene of such domestic . 这是一派天伦之乐的场景。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a feeling of great happiness","cn":""},{"en":"the feeling you have when you are very pleased and excited because something good has happened","cn":""},{"en":"a feeling of very great happiness and great pleasure – used when something has a great effect on your senses","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Bliss is a state of complete happiness or joy. Marriage is often associated with this joyous feeling: people who are married and still in love are described as living in wedded bliss ."}]},"collocations":{"phrases":["ADJ. sheer The first six months of marriage were sheer bliss. | domestic | marital, married, wedded They're celebrating 25 years of wedded b","PHRASES sb's idea of bliss My idea of bliss is a hot day and an ice-cold beer."]},"media":{"uk":"media/ldoce/hwd/bre/5/bliss0205.mp3","us":"media/ldoce/hwd/ame/1/bliss.mp3"},"examples":[{"en":"My idea of bliss is a month in the Bahamas.","cn":"我理想中的极乐是在巴哈马群岛度假一个月。"},{"en":"Swimming on a hot day is sheer bliss.","cn":"热天游泳是天大的乐事。"}]},"bleed":{"collins":{"senses":[{"pos":"VERB","cn":"出血；流血","en":"When you bleed , you lose blood from your body as a result of injury or illness. 【语法信息】：V 【语法信息】：V to n His head had struck the sink and was ing... 他的头撞到了水槽上，正在流血。 He was ing profusely... 他在大出血。 She's going to to death! 她会流血而死！"},{"pos":"VERB","cn":"（颜色）渗开，弥散","en":"If the colour of one substance bleeds into the colour of another substance that it is touching, it goes into the other thing so that its colour changes in an undesirable way. 【语法信息】：V prep The colouring pigments from the skins are not allow"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if you hurt a part of your body, you accidentally damage it so that it feels painful or you cannot move it easily","cn":""},{"en":"to hurt a part of your body, especially seriously and in a way that takes a long time to get better","cn":""},{"en":"to hurt a part of your body when you fall or hit it against something, causing a dark, painful mark to form on your skin","cn":""}]},"collocations":{"phrases":["ADV. badly, heavily, profusely | easily The small blood vessels in the nose bleed easily.","PREP. from She was bleeding heavily from a head wound.","PHRASES bleed to death"]},"media":{"uk":"media/ldoce/hwd/bre/2/bleed0205.mp3","us":"media/ldoce/hwd/ame/0/bleed.mp3"},"examples":[{"en":"Keep the paint fairly dry so that the colours don't bleed into each other.","cn":"涂料尽量干一些，以免颜色相互渗透。"},{"en":"My ex-wife is bleeding me for every penny I have.","cn":"我的前妻不断地榨取我的每一分钱。"}]},"bloodshed":{"collins":{"senses":[{"pos":"N-UNCOUNT","cn":"流血事件；杀戮","en":"Bloodshed is violence in which people are killed or wounded. The government must increase the pace of reforms to avoid further . 政府必须加快改革步伐，避免发生更多的流血事件。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the killing of people, usually in fighting or war","cn":"流血事件﹐杀戮﹐残杀"}]},"collocations":{"phrases":["ADJ. further | massive, widespread","VERB + BLOODSHED cause, end in, lead to This election result could well lead to further bloodshed. | end, halt, stop | avoid, prevent"]},"media":{"uk":"media/ldoce/hwd/bre/b/bloodshed0205.mp3","us":"media/ldoce/hwd/ame/4/bloodshed.mp3"},"examples":[{"en":"The two sides called a truce to avoid further bloodshed.","cn":"双方宣布休战，以免再有人员伤亡。"},{"en":"diplomacy aimed at stopping further bloodshed","cn":"旨在阻止流血事件再次发生的外交活动"}]},"blunder":{"collins":{"senses":[{"pos":"N-COUNT","cn":"愚蠢的错误；疏忽；失误","en":"A blunder is a stupid or careless mistake. I think he made a tactical by announcing it so far ahead of time. 我认为他在时机远未成熟时就把这事说了出去是一种失策。"},{"pos":"VERB","cn":"犯愚蠢的错误；失误","en":"If you blunder , you make a stupid or careless mistake. 【语法信息】：V 【语法信息】：V-ing No doubt I had ed again... 无疑，我又犯了一个愚蠢的错误。 You're a ing fool. 你是一个大笨蛋。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a stupid mistake caused by not thinking carefully enough about what you are saying or doing, which could have serious results","cn":""},{"en":"an embarrassing and stupid mistake made in a social situation or in public","cn":""},{"en":"a very bad mistake, especially one that shows you do not know something, and that often makes other people laugh","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A blunder is an embarrassing mistake. Accidentally called your new boyfriend by your old boyfriend's name? Ouch. That's a blunder you don't want to repeat."}]},"collocations":{"phrases":["ADJ. big, major | stupid | fatal, terrible, tragic | tactical | administrative, bureaucratic, economic, political","QUANT. series","VERB + BLUNDER commit, make The minister has made a series of political blunders."]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdeblunder.mp3","us":"media/ldoce/hwd/ame/f/blunder1.mp3"},"examples":[{"en":"The government had blundered in its handling of the affair.","cn":"政府在这件事的处理上犯了大错。"},{"en":"a series of political blunders","cn":"一连串政治失误"}]},"bloke":{"collins":{"senses":[{"pos":"N-COUNT","cn":"人；家伙","en":"A bloke is a man. 【语域标签】：BRIT 英 【STYLE标签】：INFORMAL 非正式 He is a really nice . 他真是个好人。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a man","cn":"男人﹐家伙"}]},"collocations":{"phrases":["ADJ. decent, good, great, lovely, nice | average, ordinary He's an ordinary bloke, despite being famous. | funny He's a funny bloke?you neve","PHRASES the kind/sort/type of bloke He's the sort of bloke who will never let you down."]},"media":{"uk":"media/ldoce/hwd/bre/6/bloke0205.mp3","us":"media/ldoce/hwd/ame/2/bloke.mp3"},"examples":[{"en":"He seemed like a nice bloke.","cn":"他看上去像个好人。"},{"en":"He’s a nice bloke.","cn":"他这人不错。"}]},"blasphemy":{"collins":{"senses":[{"pos":"N-VAR","cn":"亵渎上帝（或宗教）的言行","en":"You can describe something that shows disrespect for God or a religion as blasphemy . He was found guilty of and sentenced to three years in jail... 他被判犯有亵渎神明罪，刑期3年。 The MP described the killings as a before God. 这位下院议员称这些谋杀是在上帝面前的公然亵渎。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something you say or do that is insulting to God or people’s religious beliefs","cn":"对上帝的亵渎﹔亵渎神明的言辞[行为]"}]},"vocab":{"pos":"n","senses":[{"en":"Saying offensive things about God or religion is blasphemy . Blasphemy can be used for offensive ideas in other areas too."}]},"collocations":{"phrases":["VERB + BLASPHEMY commit","BLASPHEMY + NOUN law","PREP. ~ against His writings were branded as obscene and a blasphemy against God.","PHRASES a charge of blasphemy"]},"media":{"uk":"media/ldoce/hwd/bre/e/blasphemy0205.mp3","us":"media/ldoce/hwd/ame/2/blasphemy.mp3"},"examples":[{"en":"Many people found the film blasphemous.","cn":"很多人觉得那部电影亵渎了神灵。"}]},"blast":{"collins":{"senses":[{"pos":"N-COUNT","cn":"爆炸","en":"A blast is a big explosion, especially one caused by a bomb. 250 people were killed in the . 250人在这次爆炸中丧生。"},{"pos":"VERB","cn":"爆炸；炸毁；炸出；炸开","en":"If something is blasted into a particular place or state, an explosion causes it to be in that place or state. If a hole is blasted in something, it is created by an explosion. 【语法信息】： be V-ed prep/adv 【语法信息】：V n with adv 【语法信息】：Also V n ad"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an enjoyable activity, especially something you do with other people, is pleasant and interesting","cn":""},{"en":"if something is fun , you enjoy it because it is very interesting and exciting","cn":""},{"en":"giving you a lot of pleasure, enjoyment and satisfaction","cn":""}]},"vocab":{"pos":"1 n v 2 n v 3 n v 4 ","senses":[{"en":"A blast is an explosion, or a sudden sharp noise. When you blast someone, you either shoot them, or hit them with a verbal explosion––a tirade of criticism."}]},"collocations":{"phrases":["ADJ. huge, powerful | bomb, nuclear, shotgun","BLAST + VERB hit sth, rip through sth, rock sth A huge bomb blast rocked central London last night.","PREP. in a/the ~ Twenty people were killed in the blast. 2 sudden rush of air/wind","ADJ. hot, icy She felt an icy blast of air.","PREP. ~ of a blast of cold air 3 sudden loud sound","ADJ. long | short | shrill","VERB + BLAST give","PREP. ~ on He gave a short blast on his trumpet."]},"media":{"uk":"media/ldoce/hwd/bre/3/blast_v0205.mp3","us":"media/ldoce/hwd/ame/7/blast1.mp3"},"examples":[{"en":"All the windows were blasted inwards with the force of the explosion.","cn":"爆炸的震动力把所有窗户都震碎到屋里。"},{"en":"The jumbo jet was blasted out of the sky.","cn":"那架巨型喷气式飞机在空中被炸成碎片。"}]},"blush":{"collins":{"senses":[{"pos":"VERB","cn":"（由于羞愧或难为情而）脸红，涨红了脸","en":"When you blush , your face becomes redder than usual because you are ashamed or embarrassed. 【语法信息】：V 【语法信息】：V colour 'Hello, Maria,' he said, and she ed again... “你好，玛丽亚，”他说，这让她脸上又泛起了红晕。 I ed scarlet at my stupidity. 我为自己的愚蠢羞愧得满脸通红。 Blush "},{"pos":"PHRASE","cn":"不让…尴尬；避免使…难为情","en":"If you spare someone's blushes or save someone's blushes , you avoid doing or saying something that will embarrass them. 【搭配模式】：V inflects 'We don't want to name the man to spare his es,' said a police spokesman. “为了不让当事人颜面扫地，我们就不指名道姓了，”一位警"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if you blush or turn red , your face becomes red because you are embarrassed","cn":""},{"en":"to become red in the face, usually because you are embarrassed 〔","cn":"通常因难为情而〕脸红"},{"en":"to feel ashamed or embarrassed about something","cn":"感到羞愧[尴尬]"}]},"vocab":{"pos":"v n","senses":[{"en":"When you blush , you turn red because you are embarrassed. And, oddly enough, women wear the make-up variety of blush to add color to their cheeks — not to appear embarrassed but to appear attractive."}]},"collocations":{"phrases":["ADV. deeply, furiously, hotly | faintly, a little, slightly | readily She blushed more readily when she was a teenager. | angrily, guiltily","VERB + BLUSH make sb Stop teasing him?you're making him blush.","PREP. at He blushed at the mention of her name. | with She blushed crimson with embarrassment.","PHRASES blush crimson/scarlet"]},"media":{"uk":"media/ldoce/hwd/bre/2/blush_v0205.mp3","us":"media/ldoce/hwd/ame/5/blush1.mp3"},"examples":[{"en":"I blush to admit it, but I quite like her music.","cn":"不好意思，但我得承认我很喜欢她的音乐。"},{"en":"She blushed furiously at the memory of the conversation.","cn":"她一想起那次谈话就气得满脸通红。"}]},"bleeding":{"collins":{"senses":[{"pos":"ADJ","cn":"该死的；讨厌的","en":"Bleeding is used by some people to emphasize what they are saying, especially when they feel strongly about something or dislike something. 【搭配模式】：ADJ n 【语用信息】：emphasis 【语域标签】：BRIT 英 【STYLE标签】：INFORMAL 非正式 【STYLE标签】：RUDE 无礼"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the condition of losing blood from your body","cn":"流血﹐失血"},{"en":"→ haemorrhage : Use pressure to control the bleeding .","cn":"用力压住伤口止血。 The bleeding had almost stopped . 血基本上已经止住了。 He died of internal bleeding . 他死于内出血。 severe/heavy bleeding (= w"},{"en":"an offensive way of emphasizing something when you are angry","cn":"讨厌的﹐他妈的﹐该死的"}]},"collocations":{"phrases":["ADJ. heavy, massive | uncontrollable | internal","VERB + BLEEDING have, suffer from | cause | control, staunch, stem, stop","PREP. ~ from Some drugs can cause bleeding from the small intestine."]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdebleeding.mp3","us":"media/ldoce/hwd/ame/b/laadbleeding.mp3"},"examples":[{"en":"Press firmly on the wound to stop the bleeding.","cn":"用力压住伤口止血。"},{"en":"Get your bleeding hands off my car!","cn":"拿开你的臭手﹐不要碰我的汽车！"}]},"bloc":{"collins":{"senses":[{"pos":"N-COUNT","cn":"国家集团；阵营；共同体","en":"; A bloc is a group of countries which have similar political aims and interests and that act together over some issues. ...the former Soviet . 前苏联集团 ...the world's largest trading . 世界上最大的贸易共同体"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large group of people or countries with the same political aims, working together","cn":"集团﹐阵营"}]},"collocations":{"phrases":["ADJ. large, solid, substantial A solid bloc of union members support the decision. | economic, military, trading | Communist, Eastern, Sovie","PREP. in/within a/the ~ There have been growing tensions within the trading bloc.","PHRASES en bloc (= all together; all at the same time)"]},"media":{"uk":"media/ldoce/hwd/bre/8/bloc0205.mp3","us":"media/ldoce/hwd/ame/b/bloc1.mp3"},"examples":[{"en":"the former Soviet bloc","cn":"苏联阵营"}]},"blouse":{"collins":{"senses":[{"pos":"N-COUNT","cn":"宽松的女短衫；女式衬衫","en":"A blouse is a kind of shirt worn by a girl or woman."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a shirt for women","cn":"女式宽松短衫﹐女衬衫"}]},"collocations":{"phrases":["ADJ. long-sleeved, short-sleeved, sleeveless | high-necked | cotton, silk, etc. | embroidered, frilled, frilly | see-through | school","VERB + BLOUSE have on, wear | put on | button up, unbutton | take off"]},"media":{"uk":"media/ldoce/hwd/bre/0/blouse0205.mp3","us":"media/ldoce/hwd/ame/1/blouse.mp3"},"examples":[{"en":"a silk blouse","cn":"丝质女衬衫"}]},"blockade":{"collins":{"senses":[{"pos":"N-COUNT","cn":"封锁；阻塞","en":"A blockade of a place is an action that is taken to prevent goods or people from entering or leaving it. 【搭配模式】：oft N of n Striking lorry drivers agreed to lift their s of main roads... 罢工的卡车司机们同意解除对主干道的封堵。 It's not yet clear who will actua"},{"pos":"VERB","cn":"阻塞；封锁","en":"If a group of people blockade a place, they stop goods or people from reaching that place. If they blockade a road or a port, they stop people using that road or port. 【语法信息】：V n 【语法信息】：Also V-ed Truck drivers have d roads to show their ang"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the surrounding of an area by soldiers or ships to stop people or supplies entering or leaving 〔","cn":"对某地的〕封锁"},{"en":"something that is used to stop vehicles or people entering or leaving a place","cn":"堵塞物﹐障碍物"},{"en":"if someone or something is in the way , they are in a position that stops you from going where you want","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A blockade is an obstacle that stands between you and something you're trying to reach. After a robbery, police might set up a blockade around the neighborhood to catch the thief."}]},"collocations":{"phrases":["ADJ. complete, total | tight | partial | virtual | economic, military, naval","VERB + BLOCKADE impose | end, lift, remove | enforce, maintain | tighten | ease, relax | break, get through, run They attempted to break the","PREP. ~ against the need to enforce a naval blockade against the country | ~ around/round a blockade around the city | ~ by the blockade by "]},"media":{"uk":"media/ldoce/hwd/bre/c/blockade_n0205.mp3","us":"media/ldoce/hwd/ame/9/l3blockade.mp3"},"examples":[{"en":"The police set up blockades on highways leading out of the city.","cn":"警察在出城的公路上设了路障。"},{"en":"an economic blockade (= stopping goods from entering or leaving a country)","cn":"经济封锁"}]},"blitz":{"collins":{"senses":[{"pos":"VERB","cn":"以闪电战空袭；以闪电战攻击","en":"If a city or building is blitzed during a war, it is attacked by bombs dropped by enemy aircraft. 【语法信息】： be V-ed 【语法信息】：V n In the autumn of 1940 London was ed by an average of two hundred aircraft a night... 1940年秋，伦敦平均每晚遭到200架飞机的空袭。 They"},{"pos":"N-PROPER","cn":"德军对英国城市的空袭，伦敦大轰炸（1940年至1941年间）","en":"The heavy bombing of British cities by German aircraft in 1940 and 1941 is referred to as the Blitz . 【搭配模式】： the N"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sudden military attack, especially from the air","cn":"闪电般的猛烈袭击〔尤指空袭〕﹔闪电战"},{"en":"a period of great effort in order to deal with something quickly and completely","cn":"闪电行动"},{"en":"a big effort to make people notice something or buy something 〔","cn":"为吸引注意力或吸引人们购买某物的〕大规模行动"}]},"vocab":{"pos":"n v","senses":[{"en":"A sudden, overwhelming military attack during war is a blitz . Sometimes a major blitz can lead to the end of a conflict."}]},"collocations":{"phrases":["ADJ. bombing | wartime","VERB + BLITZ carry out","PREP. during/in a/the ~ Many people died in the London blitz. | ~ on Enemy bombers carried out a blitz on the city. 2 campaign; sudden, grea","ADJ. marketing, media, sales","VERB + BLITZ have, launch, mount We decided to have a blitz on the kitchen (= to clean the kitchen thoroughly) .","PREP. ~ on a blitz on illegal parking"]},"media":{"uk":"media/ldoce/hwd/bre/5/blitz0205.mp3","us":"media/ldoce/hwd/ame/a/blitz1.mp3"},"examples":[{"en":"Five shops were damaged in a firebomb blitz.","cn":"在一次燃烧弹袭击中有五家店铺被烧毁。"},{"en":"an advertising/a media blitz (= a lot of information about sth on television, in newspapers, etc.)","cn":"集中火力的广告/媒体宣传"}]},"bladder":{"collins":{"senses":[{"pos":"N-COUNT","cn":"膀胱","en":"; Your bladder is the part of your body where urine is stored until it leaves your body."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the organ in your body that holds urine (= waste liquid ) until it is passed out of your body","cn":"膀胱"},{"en":"a bag of skin, leather, or rubber, for example inside a football, that can be filled with air or liquid 〔","cn":"可充气或充水的〕皮囊﹐气囊〔如足球的内胆〕"}]},"collocations":{"phrases":["ADJ. full | irritable, weak","VERB + BLADDER empty","BLADDER + NOUN control | cancer, infection, problem He died of bladder cancer."]},"media":{"uk":"media/ldoce/hwd/bre/b/bladder0205.mp3","us":"media/ldoce/hwd/ame/2/bladder.mp3"}},"blameless":{"collins":{"senses":[{"pos":"ADJ-GRADED","cn":"无可责备的；没有过错的；清白的","en":"Someone who is blameless has not done anything wrong. He feels he is ... 他觉得自己并没有什么过失。 The US itself, of course, is not entirely in trading matters. 当然，美国本身在贸易问题上也不是完全没有任何过错。 ...a life. 清白的一生"}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if someone is innocent of a crime, they did not do it - use this especially about someone that other people think is guilty","cn":""},{"en":"if someone is not guilty of a crime, they did not do it - use this especially when a court has officially decided that someone did not do a crime","cn":""},{"en":"not having done anything wrong, or not responsible for something bad that has happened","cn":""}]},"collocations":{"phrases":["VERBS be","ADV. quite (= totally) She herself was quite blameless. | far from, not entirely Johnson himself was far from blameless."]},"media":{"uk":"media/ldoce/hwd/bre/9/blameless0205.mp3","us":"media/ldoce/hwd/ame/9/blameless.mp3"},"examples":[{"en":"None of us is entirely blameless in this matter.","cn":"在这件事上我们没有一个人是完全没有责任的。"},{"en":"to lead a blameless life","cn":"活得清白"}]},"blanket":{"collins":{"senses":[{"pos":"N-COUNT","cn":"毯子；毛毯","en":"A blanket is a large square or rectangular piece of thick cloth, especially one which you put on a bed to keep you warm."},{"pos":"N-COUNT","cn":"覆盖层","en":"A blanket of something such as snow is a continuous layer of it which hides what is below or beyond it. 【搭配模式】：usu sing The mud disappeared under a of snow... 泥巴被积雪盖住了。 Cold damp air brought in the new year under a of fog. 厚厚的一层雾伴着阴冷潮湿的空气迎来"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a cover for a bed, usually made of wool","cn":"毯子﹐毛毯"},{"en":"a thick covering or area of something","cn":"厚（的覆盖）层"},{"en":"something that makes it hard for you to find information or the truth about something 〔","cn":"使信息或真相难以被发现的〕蒙蔽之物"}]},"collocations":{"phrases":["ADJ. heavy, thick | thin | warm | electric","VERB + BLANKET cover sb with, wrap sb in | draw up, pull up She pulled the blanket up and went to sleep. | kick off, push off, throw off","PREP. beneath/under a/the ~ They shivered under their thin blankets."]},"media":{"uk":"media/ldoce/hwd/bre/8/blanket_adj0205.mp3","us":"media/ldoce/hwd/ame/3/blanket1.mp3"},"examples":[{"en":"Snow soon blanketed the frozen ground.","cn":"冻土上很快就形成了一层厚厚的积雪。"},{"en":"( figurative ) The trial was conducted under a blanket of secrecy.","cn":"审讯在高度保密下进行。"}]},"blueprint":{"collins":{"senses":[{"pos":"N-COUNT","cn":"蓝图；计划；设想；构想","en":"A blueprint for something is a plan or set of proposals that shows how it is expected to work. 【搭配模式】：usu N for n The country's president will offer delegates his for the country's future. 该国总统会向代表们展示他构想的国家未来发展的蓝图。 ...the of a new plan of e"},{"pos":"N-COUNT","cn":"（建筑、设计的）蓝图","en":"A blueprint of an architect's building plans or a designer's pattern is a photographic print consisting of white lines on a blue background. Blueprints contain all of the information that is needed to build or make something. 【搭配模式】：usu wit"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that you have decided to do, and the methods you will use to do it","cn":""},{"en":"a detailed plan explaining exactly how to achieve something","cn":""},{"en":"a carefully designed plan for achieving something that is difficult and may take a long time","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A blueprint is a guide for making something — it's a design or pattern that can be followed. Want to build the best tree house ever? Draw up a blueprint and follow the design carefully."}]},"collocations":{"phrases":["ADJ. new | final | economic, personal","VERB + BLUEPRINT have The government does not have a blueprint for reform. | create, develop, draw up | act as, form, provide, serve as The ","PREP. for a blueprint for change"]},"media":{"uk":"media/ldoce/hwd/bre/3/blueprint0205.mp3","us":"media/ldoce/hwd/ame/f/blueprint.mp3"},"examples":[{"en":"DNA carries the genetic blueprint which tells any organism how to build itself.","cn":"脱氧核糖核酸带有表明有机体形成方式的遗传型板。"},{"en":"a blueprint for the privatization of health care","cn":"保健私有化方案"}]},"blaze":{"collins":{"senses":[{"pos":"VERB","cn":"熊熊燃烧","en":"When a fire blazes , it burns strongly and brightly. 【语法信息】：V 【语法信息】：V-ing Three people died as wreckage d, and rescuers fought to release trapped drivers... 汽车残骸熊熊燃烧，三人葬身火海，救援人员奋力解救被困的司机们。 The log fire was blazing merrily. 木柴烧得正旺。 ...a bla"},{"pos":"N-COUNT","cn":"大火；烈火","en":"A blaze is a large fire which is difficult to control and which destroys a lot of things. 【搭配模式】：usu sing 【FIELD标签】：JOURNALISM 新闻 Two firemen were hurt in a which swept through a tower block last night. 昨晚，一场大火吞噬了一座高层建筑，两位消防员被烧伤。"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"flames that burn in an uncontrolled way and destroy or damage things","cn":""},{"en":"the bright parts of a fire that you see burning in the air","cn":""},{"en":"a large and dangerous fire – used especially in news reports","cn":""}]},"vocab":{"pos":"1 n v 2 n v 3 n","senses":[{"en":"A blaze is a bright, strong flame. A raging fire is blazing and you can also say other types of shining, like with talent, are types of blazing ."}]},"collocations":{"phrases":["ADJ. fierce, intense, massive","VERB + BLAZE attend, fight, tackle The fire brigade attended the blaze. | control, bring/get under control | extinguish, put out | fan Stron","BLAZE + VERB spread, sweep through sth The blaze swept through the whole building.","PREP. in a/the ~ The antiques were destroyed in a blaze last year."]},"media":{"uk":"media/ldoce/hwd/bre/8/blaze_v0205.mp3","us":"media/ldoce/hwd/ame/a/blaze1.mp3"},"examples":[{"en":"The department is blazing a trail in the field of laser surgery.","cn":"这个部门正在为激光外科学领域开辟一条新路。"},{"en":"The sun blazed down from a clear blue sky.","cn":"耀眼的阳光从清澈蔚蓝的天空中照射下来。"}]}});
